import java.util.Scanner;

public class Main {
    static String s;

    static String processString() {
        for (int index = 1; index < s.length() - 2; ++index) {
            if (s.charAt(index) == 'a' && s.charAt(index + 1) == 't') {
                s = s.substring(0, index) + "@" + s.substring(index + 2);
                break;
            }
        }
        for (int index = 1; index < s.length() - 3; ++index) {
            if (s.charAt(index) == 'd' && s.charAt(index + 1) == 'o' && s.charAt(index + 2) == 't') {
                s = s.substring(0, index) + "." + s.substring(index + 3);
            }
        }
        return s;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNext()) {
            s = scanner.next();
            System.out.println(processString());
        }
        scanner.close();
    }
}
